import { chromium } from 'playwright';

const browser = await chromium.launch({ args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });

const errors = [];
page.on('console', (msg) => {
  if (msg.type() === 'error') errors.push(msg.text());
});
page.on('pageerror', (err) => errors.push(String(err)));

await page.goto('http://localhost:4299/events', { waitUntil: 'networkidle' });
await page.waitForSelector('.event-list__item');
await page.screenshot({ path: '/tmp/solo02-01-list.png', fullPage: true });

const filterResult = await page.locator('.event-list__item').count();
console.log('Events in list:', filterResult);

// filter by venue
await page.selectOption('select[name="venueId"]', { label: 'Kulturhaus Südtor' });
await page.click('button[type="submit"]');
await page.waitForTimeout(500);
const filteredCount = await page.locator('.event-list__item').count();
console.log('Events filtered by venue (expect 3):', filteredCount);
await page.screenshot({ path: '/tmp/solo02-02-filtered.png', fullPage: true });

// reset and open first event
await page.click('button:has-text("Zurücksetzen")');
await page.waitForTimeout(500);
await page.locator('.event-list__item a').first().click();

await page.waitForSelector('h1');
await page.screenshot({ path: '/tmp/solo02-03-detail.png', fullPage: true });
console.log('Detail URL:', page.url());

await page.click('text=Plätze auswählen');
await page.waitForSelector('.seat-plan');
await page.screenshot({ path: '/tmp/solo02-04-seatplan.png', fullPage: true });

// select two free seats
const freeSeats = page.locator('button.seat--free');
const freeCount = await freeSeats.count();
console.log('Free seats available:', freeCount);
await freeSeats.nth(0).click();
await freeSeats.nth(1).click();
await page.waitForSelector('.selection-summary');
await page.screenshot({ path: '/tmp/solo02-05-selection.png', fullPage: true });

const total = await page.locator('.selection-summary__total').textContent();
console.log('Total price shown:', total);

await page.fill('input[name="customerName"]', 'Erika Mustermann');
await page.fill('input[name="customerEmail"]', 'erika@example.com');
await page.click('button[type="submit"].button--primary');

await page.waitForURL('**/bookings/*');
await page.waitForSelector('.booking-detail__seats');
await page.screenshot({ path: '/tmp/solo02-06-booking.png', fullPage: true });
console.log('Booking URL:', page.url());

const reference = page.url().split('/').pop();
console.log('Booking reference:', reference);

// lookup flow: go to /bookings, enter reference, verify navigation
await page.goto('http://localhost:4299/bookings', { waitUntil: 'networkidle' });
await page.fill('input[name="reference"]', reference);
await page.click('button[type="submit"]');
await page.waitForURL(`**/bookings/${reference}`);
await page.waitForSelector('.booking-detail__seats');
console.log('Lookup succeeded, URL:', page.url());

// cancel
await page.click('button:has-text("Buchung stornieren")');
await page.waitForSelector('.booking-status--cancelled');
await page.screenshot({ path: '/tmp/solo02-07-cancelled.png', fullPage: true });
console.log('Cancelled status visible');

console.log('Console/page errors:', errors);

await browser.close();

